import {transform,pushSlope,odeRhs,riccati,coordinates,reduced,reducedSolution} from './lie-math.mjs';
export {fmt,colors,range,note,legend,frame,sampled,plot,bindRanges,directionField};
const $=s=>document.querySelector(s);
const fmt=(v,n=3)=>Number.isFinite(v)?(Math.abs(v)<.5*10**(-n)?0:v).toLocaleString('es-ES',{maximumFractionDigits:n,minimumFractionDigits:n}):'no definido';
const colors={original:'#c3b6ff',changed:'#6ce2bc',ghost:'#b8c2da',red:'#ffac95'};
const range=(id,label,min,max,step,value)=>`<div class="field"><label for="${id}">${label}<output id="${id}-value" for="${id}">${fmt(value)}</output></label><input class="range" type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const note=(title,text)=>`<div class="insight"><span class="insight-symbol">∴</span><p><strong>${title}</strong>${text}</p></div>`;
const legend=()=>`<div class="plot-legend"><span><i style="background:${colors.original}"></i>Original</span><span><i style="background:${colors.changed}"></i>Transformado</span></div>`;
const frame=(title,chart,controls)=>`<div class="lab lie-lab"><div class="viz"><div class="viz-header"><span>${title}</span><span class="viz-tag">Modelo matemático</span></div><div id="lie-chart">${chart}</div>${legend()}</div><div class="control-panel">${controls}</div></div>`;
function sampled(fn,a,b,n=260){return Array.from({length:n+1},(_,i)=>{try{return fn(a+(b-a)*i/n);}catch{return [NaN,NaN];}});}
function plot({title='Gráfica',bounds=[-4,4,-4,4],paths=[],points=[],segments=[],labels=['x','y'],equal=false}){
 let [xmin,xmax,ymin,ymax]=bounds;const W=560,H=380,L=45,T=22,R=25,B=40;
 if(equal){const mid=(xmin+xmax)/2,half=(ymax-ymin)*(W-L-R)/(H-T-B)/2;xmin=mid-half;xmax=mid+half;}
 const X=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),Y=y=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);
 const ok=p=>p?.every(Number.isFinite)&&p[0]>=xmin&&p[0]<=xmax&&p[1]>=ymin&&p[1]<=ymax;
 let grid='';for(let i=0;i<=4;i++){let xv=xmin+(xmax-xmin)*i/4,yv=ymin+(ymax-ymin)*i/4;grid+=`<path d="M${X(xv)} ${T}V${H-B}M${L} ${Y(yv)}H${W-R}" stroke="#323b57" stroke-width=".7"/><text x="${X(xv)}" y="${H-B+19}" text-anchor="middle">${fmt(xv,1)}</text><text x="${L-8}" y="${Y(yv)+4}" text-anchor="end">${fmt(yv,1)}</text>`;}
 const path=ps=>{let d='',prev=null;for(const p of ps){if(!ok(p)){prev=null;continue;}const jump=prev&&(Math.abs(X(p[0])-X(prev[0]))>70||Math.abs(Y(p[1])-Y(prev[1]))>85);d+=(prev&&!jump?'L':'M')+X(p[0]).toFixed(2)+' '+Y(p[1]).toFixed(2)+' ';prev=p;}return d;};
 return `<svg class="lie-plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="${title}"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}" fill="#141c32"/>${grid}${xmin<=0&&xmax>=0?`<path d="M${X(0)} ${T}V${H-B}" stroke="#8994af"/>`:''}${ymin<=0&&ymax>=0?`<path d="M${L} ${Y(0)}H${W-R}" stroke="#8994af"/>`:''}${segments.map(({a,b,color='#65718c',width=1})=>ok(a)&&ok(b)?`<path d="M${X(a[0])} ${Y(a[1])}L${X(b[0])} ${Y(b[1])}" stroke="${color}" stroke-width="${width}"/>`:'').join('')}${paths.map(p=>`<path d="${path(p.data)}" fill="none" stroke="${p.color||colors.original}" stroke-width="${p.width||2.4}" ${p.dash?'stroke-dasharray="5 6"':''}/>`).join('')}${points.map(p=>ok(p.xy)?`<circle cx="${X(p.xy[0])}" cy="${Y(p.xy[1])}" r="${p.r||6}" fill="${p.color||colors.changed}" stroke="#151b30" stroke-width="2"/><text x="${X(p.xy[0])+10}" y="${Y(p.xy[1])-9}" fill="${p.color||colors.changed}">${p.label||''}</text>`:'').join('')}<text x="${W-12}" y="${H-B+3}" text-anchor="end" class="axis-label">${labels[0]}</text><text x="${L+8}" y="15" class="axis-label">${labels[1]}</text></svg>`;
}
function bindRanges(ids,update){ids.forEach(id=>$('#'+id).oninput=()=>{const v=Number($('#'+id).value);$('#'+id+'-value').textContent=fmt(v);update();});}
function geometry(root){
 root.innerHTML=frame('FIGURA E INVARIANTE','',`<h3>Mover sin cambiar el objeto</h3><p class="helper">El punto verde es la imagen del punto violeta. La ecuación decide si ambos pertenecen al mismo objeto.</p><div class="field"><label for="geometry-model">Modelo</label><select id="geometry-model"><option value="rotation">Rotación · círculo</option><option value="line">Dilatación · recta</option><option value="rational">Mapa racional · hipérbola</option></select></div><div id="geometry-controls"></div><div id="geometry-result" class="result-box" aria-live="polite"></div>`)+note('Una simetría conserva el conjunto, no cada punto.','Compara la rotación con la dilatación: la primera conserva el radio; la segunda conserva una dirección. El ejemplo racional conserva una combinación de coordenadas.')+`<details class="extension"><summary>Puente con el triángulo de Hamermesh</summary><div class="detail-body"><p>Un triángulo solo vuelve a encajar tras giros concretos (0°,120°,240°). Un círculo vuelve a encajar para cualquier ángulo. Esta posibilidad de mover el parámetro continuamente prepara el paso de grupos discretos a grupos de Lie.</p><a class="text-link" href="#material/hamermesh/1/1/explorar">Revisar el laboratorio del triángulo</a></div></details>`;
 const setup=()=>{const k=$('#geometry-model').value;$('#geometry-controls').innerHTML=range('geometry-e',k==='rotation'?'Ángulo ε (radianes)':'Parámetro ε',-2,2,.02,.4)+(k==='line'?`<div class="field"><label for="line-offset">Recta que comprobar</label><select id="line-offset"><option value="0">y = x/2 · pasa por el origen</option><option value="1">y = x/2 + 1 · desplazada</option></select></div>`:'');bindRanges(['geometry-e'],update);if($('#line-offset'))$('#line-offset').onchange=update;update();};
 const update=()=>{const k=$('#geometry-model').value,e=+$('#geometry-e').value,b=+($('#line-offset')?.value||0);let base,changed,paths,info,title,valid=true;
  if(k==='rotation'){base=[2*Math.cos(.35),2*Math.sin(.35)];changed=transform('rotation',...base,e);paths=[{data:sampled(t=>[2*Math.cos(t),2*Math.sin(t)],0,Math.PI*2)},{data:sampled(t=>[2*Math.cos(.35+t),2*Math.sin(.35+t)],0,e),color:colors.changed,width:4}];info=`<span class="mini-label">INVARIANTE · RADIO AL CUADRADO</span><div class="result-equation">x²+y² = ${fmt(4)}</div><p>x̄²+ȳ² = ${fmt(changed[0]**2+changed[1]**2)}.</p><p class="helper">ε=${fmt(e)} rad = ${fmt(e*180/Math.PI,1)}°. Ambos puntos están en el círculo de radio 2.</p>`;title='Círculo de radio 2, punto original y punto rotado';}
  else if(k==='line'){base=[1,.5+b];changed=transform('scale',...base,e);paths=[{data:sampled(x=>[x,.5*x+b],-4,4)},{data:sampled(x=>[x,.5*x+b*Math.exp(e)],-4,4),color:colors.changed,dash:true}];const residual=changed[1]-.5*changed[0]-b;info=`<span class="mini-label">COMPROBACIÓN · ȳ−x̄/2−b</span><div class="result-equation">${fmt(residual,4)}</div><p class="${Math.abs(residual)<1e-9?'pass':'fail'}">${Math.abs(residual)<1e-9?'El punto transformado satisface la misma recta.':'El punto ya no pertenece a la recta original.'}</p><p class="helper">El residuo general es b(e<sup>ε</sup>−1). Con b=0 se anula para todo ε; con b=1, solo para ε=0.</p>`;title='Recta original y recta transformada por dilatación';}
  else{base=[.4,.625];valid=1-e*base[1]>1e-8;changed=valid?transform('rational',...base,e):null;paths=[{data:sampled(x=>[x,1/(2-x)],-4,4)}];info=`<span class="mini-label">INVARIANTE · I=x+1/y</span><div class="result-equation">I = 2</div><p>${changed?'Ī = '+fmt(changed[0]+1/changed[1])+'. El parámetro se cancela.':'El flujo llega al polo en ε=1,600. No se puede atravesar.'}</p><p class="helper">X=x+ε, Y=y/(1−εy). El intervalo conectado desde la identidad para este punto es ε&lt;1,600.</p>`;title='Hipérbola x más uno sobre y igual a 2 y movimiento del punto';}
  $('#lie-chart').innerHTML=plot({title,equal:true,paths,points:[{xy:base,color:colors.original,label:'P'},...(changed?[{xy:changed,label:'Tε(P)'}]:[])]});$('#geometry-result').innerHTML=info;
 };$('#geometry-model').onchange=setup;setup();
}
function group(root){
 root.innerHTML=frame('DOS PASOS, UN MISMO MAPA','',`<h3>Compón dos transformaciones</h3><p class="helper">Empieza en P, aplica a y después b. El resultado verde debe coincidir con el mapa de parámetro a+b.</p><div class="field"><label for="flow-model">Flujo</label><select id="flow-model"><option value="hyperbola">Hipérbola · Tε=(xy/(y−ε), y−ε)</option><option value="scale">Dilatación · Tε=(e^εx, e^εy)</option></select></div>${range('flow-a','Primer paso a',-1.2,2.4,.02,.4)}${range('flow-b','Segundo paso b',-2.4,2.4,.02,.3)}<div class="button-row"><button id="flow-inverse" class="primary-button">Usar b = −a</button><button id="flow-reset" class="quiet-button">Identidad a = b = 0</button></div><div id="flow-result" class="result-box" aria-live="polite"></div>`)+`<div class="two-col"><div class="card"><h3>Cuatro condiciones, una ley</h3><div class="axioms"><div class="axiom"><strong>Cierre local</strong>Los parámetros se suman donde el recorrido está definido.</div><div class="axiom"><strong>Asociatividad</strong>(a+b)+c = a+(b+c).</div><div class="axiom"><strong>Identidad</strong>T₀(P)=P.</div><div class="axiom"><strong>Inverso</strong>T₋ₐ(Tₐ(P))=P.</div></div></div><div class="card"><h3>Parámetro y factor no son lo mismo</h3><p>En una dilatación, a y b son parámetros logarítmicos. Los factores son e<sup>a</sup> y e<sup>b</sup>; se multiplican para dar e<sup>a+b</sup>.</p><p>El flujo exponencial recorre escalas positivas. Los mapas racionales se estudian localmente para no atravesar sus polos.</p></div></div>`;
 const update=()=>{const k=$('#flow-model').value,a=+$('#flow-a').value,b=+$('#flow-b').value,P=k==='hyperbola'?[.5,2]:[1,1.5];const valid=k==='scale'||(2-a>1e-8&&2-a-b>1e-8);let A=null,B=null,D=null;if(valid){A=transform(k,...P,a);B=transform(k,...A,b);D=transform(k,...P,a+b);}const bounds=k==='hyperbola'?[-.2,Math.max(4.2,(B?.[0]||0)*1.2),-.2,Math.max(4.2,(B?.[1]||0)*1.2)]:[-.2,Math.max(6,(B?.[0]||0)*1.2,(A?.[0]||0)*1.2),-.2,Math.max(8,(B?.[1]||0)*1.2,(A?.[1]||0)*1.2)];const paths=[{data:k==='hyperbola'?sampled(y=>[1/y,y],.22,4.2):sampled(t=>[t,1.5*t],0,bounds[1])}];$('#lie-chart').innerHTML=plot({title:'Composición del flujo: punto inicial, primer paso y resultado final',bounds,paths,points:[{xy:P,color:colors.ghost,label:'P'},...(A?[{xy:A,color:colors.original,label:'Ta(P)'},{xy:B,label:'Tb∘Ta(P)'}]:[])]});$('#flow-result').innerHTML=`<span class="mini-label">LEY DE COMPOSICIÓN</span><div class="result-equation">a+b = ${fmt(a+b)}</div>${valid?`<p>T<sub>b</sub>∘T<sub>a</sub>(P)=(${fmt(B[0])}; ${fmt(B[1])})</p><p>T<sub>a+b</sub>(P)=(${fmt(D[0])}; ${fmt(D[1])})</p><p class="pass">Coinciden · diferencia ${fmt(Math.hypot(B[0]-D[0],B[1]-D[1]),6)}</p><p class="helper">${k==='hyperbola'?'Producto conservado: x̄ȳ = '+fmt(B[0]*B[1])+'.':'Factor total: e^(a+b) = '+fmt(Math.exp(a+b))+'.'}</p>`:'<p class="fail">El recorrido alcanza o atraviesa el polo ε=2. Reduce a o a+b para permanecer en el dominio del flujo.</p>'}`;};
 bindRanges(['flow-a','flow-b'],update);$('#flow-model').onchange=()=>{['flow-a','flow-b'].forEach((id,i)=>{$('#'+id).value=[.4,.3][i];$('#'+id+'-value').textContent=fmt([.4,.3][i]);});update();};$('#flow-inverse').onclick=()=>{$('#flow-b').value=-Number($('#flow-a').value);$('#flow-b-value').textContent=fmt(+$('#flow-b').value);update();};$('#flow-reset').onclick=()=>{['flow-a','flow-b'].forEach(id=>{$('#'+id).value=0;$('#'+id+'-value').textContent=fmt(0);});update();};update();
}
function directionField(fn,bounds){const [xmin,xmax,ymin,ymax]=bounds,segments=[];for(let i=1;i<15;i++)for(let j=1;j<12;j++){const x=xmin+(xmax-xmin)*i/15,y=ymin+(ymax-ymin)*j/12,p=fn(x,y);if(!Number.isFinite(p))continue;const norm=Math.hypot(1,p*(xmax-xmin)/(ymax-ymin)),dx=(xmax-xmin)*.012/norm,dy=p*dx;segments.push({a:[x-dx,y-dy],b:[x+dx,y+dy]});}return segments;}
function invariance(root){
 root.innerHTML=frame('CAMPO DE PENDIENTES Y TANGENTES','',`<h3>Transforma el punto y su pendiente</h3><div class="field"><label for="ode-model">Ecuación</label><select id="ode-model"><option value="simple">y′ = xy³ · escala opuesta</option><option value="projective">y′ = (xy+1)³/x⁵ + 1/x² · mapa racional</option></select></div><div id="ode-extra"></div>${range('ode-x','Coordenada inicial x',.7,1.6,.02,1)}${range('ode-y','Coordenada inicial y',.2,1.2,.02,.6)}${range('ode-e','Parámetro ε',-.8,.8,.02,.3)}<div id="ode-result" class="result-box" aria-live="polite"></div>`)+`<div class="chain-rule card"><span class="mini-label">LA REGLA DE LA CADENA</span><h3>p̄ = (Yₓ + Yᵧp) / (Xₓ + Xᵧp)</h3><p>La tangente violeta tiene pendiente F(x,y). La tangente verde es su imagen. Si coincide con la dirección del campo en (X,Y), has comprobado la identidad en ese punto.</p><div id="ode-proof"></div></div>`+note('Las dos cantidades deben cambiar juntas.','El punto y el vector tangente forman la prueba. El campo gris describe la misma EDO antes y después; la comparación numérica ilustra la identidad algebraica de los apuntes.');
 const setup=()=>{$('#ode-extra').innerHTML=$('#ode-model').value==='simple'?`<div class="field"><label for="ode-test">Transformación que probar</label><select id="ode-test"><option value="symmetry">X=e^εx, Y=e^(−ε)y · simetría</option><option value="wrong">X=e^εx, Y=e^εy · contraejemplo</option></select></div>`:'';if($('#ode-test'))$('#ode-test').onchange=update;update();};
 const update=()=>{const model=$('#ode-model').value,k=model==='projective'?'projective':$('#ode-test').value==='wrong'?'scale':'odeScale',x=+$('#ode-x').value,y=+$('#ode-y').value,e=+$('#ode-e').value,F=odeRhs[model],p=F(x,y),valid=k!=='projective'||1+e*x>1e-8;let P=null,pb=NaN,rhs=NaN;if(valid){P=transform(k,x,y,e);pb=pushSlope(k,x,y,e,p);rhs=F(...P);}const bounds=[-.15,4,-.4,3],segs=directionField(F,bounds);const tangent=(pt,m,col)=>{const d=.26/Math.hypot(1,m);return {a:[pt[0]-d,pt[1]-m*d],b:[pt[0]+d,pt[1]+m*d],color:col,width:4};};segs.push(tangent([x,y],p,colors.original));if(P)segs.push(tangent(P,pb,colors.changed));const paths=model==='simple'?[{data:sampled(t=>[t,1/Math.sqrt(1/y**2+x*x-t*t)],0,3.5),color:colors.original,width:2},{data:sampled(t=>{const pt=[t,1/Math.sqrt(1/y**2+x*x-t*t)];return transform(k,...pt,e);},0,3.5),color:colors.changed,width:2,dash:true}]:[];
 $('#lie-chart').innerHTML=plot({title:'Campo de pendientes de la EDO con tangente original y transformada',bounds,paths,points:[{xy:[x,y],color:colors.original,label:'(x,y)'},...(P?[{xy:P,label:'(X,Y)'}]:[])],segments:segs});const error=pb-rhs;$('#ode-result').innerHTML=`<span class="mini-label">PENDIENTE ORIGINAL</span><p>p=F(x,y)=${fmt(p,5)}</p>${P?`<div class="slope-comparison"><span>Pendiente transformada<strong>${fmt(pb,5)}</strong></span><span>F(X,Y)<strong>${fmt(rhs,5)}</strong></span></div><p class="${Math.abs(error)<1e-7?'pass':'fail'}">Diferencia: ${fmt(error,6)} · ${Math.abs(error)<1e-7?'coinciden en este punto':'no coinciden'}</p>`:'<p class="fail">El flujo cruza 1+εx=0. Este punto no tiene imagen admisible desde ε=0.</p>'}`;
 $('#ode-proof').innerHTML=model==='projective'?'<p class="math">p̄=(1+εx)²p<br>F(X,Y)=(1+εx)²F(x,y)</p><p>La misma potencia aparece en los dos términos del lado derecho. Excluye x=0 y 1+εx=0.</p>':k==='scale'?'<p class="math">p̄=p<br>F(X,Y)=e<sup>4ε</sup>F(x,y)</p><p>Estos factores difieren para ε≠0 cuando F(x,y)≠0. La dilatación con el mismo peso en ambas coordenadas falla.</p>':'<p class="math">p̄=e<sup>−2ε</sup>p<br>F(X,Y)=e<sup>−2ε</sup>F(x,y)</p><p>El conjunto de curvas solución se conserva. Para y≠0, la constante K de y=±1/√(K−x²) cambia a e<sup>2ε</sup>K. También existe y=0.</p>';
 };bindRanges(['ode-x','ode-y','ode-e'],update);$('#ode-model').onchange=setup;setup();
}
const reductions={
 riccati:{name:'Riccati',eq:'y′ = y² − y/x − 1/x²',map:'X=e^εx, Y=e^(−ε)y',coords:'r=xy, s=ln|x|',newEq:'ds/dr = 1/(r²−1)',integral:'s = ½ ln|(r−1)/(r+1)| + C₀',back:'y = 1/x + 2x/(C−x²)',domain:'x≠0 y C−x²≠0. Las soluciones r=±1 dan y=±1/x; el cambio s(r) no las representa.',steps:['Calcula r=xy: al multiplicar X por Y se cancelan los factores exponenciales. ln|X|=ln|x|+ε.','dr/dx=y+xy′=(r²−1)/x. ds/dx=1/x. Divide para obtener ds/dr=1/(r²−1), si r≠±1.','Integra por fracciones simples: 1/(r²−1)=½[1/(r−1)−1/(r+1)]. Aparece un logaritmo.','Sustituye r=xy y s=ln|x|. Reparametriza la constante para obtener y=1/x+2x/(C−x²). Añade y=1/x; y=−1/x corresponde a C=0.']},
 ratio:{name:'Cociente',eq:'y′ = y/x + x²/(x+y)',map:'X=x+ε, Y=(x+ε)y/x',coords:'r=y/x, s=x',newEq:'ds/dr = r+1',integral:'s = ½r² + r + C',back:'x = ½(y/x)² + y/x + C',domain:'x≠0 y x+y≠0. En la curva reducida excluye s=0 y r=−1, aunque la parábola se vea regular.',steps:['Y/X=y/x: r no cambia. X=x+ε: s se traslada. Las curvas de la simetría son rayos con cociente fijo.','dr/dx=(xy′−y)/x²=1/(1+r). Como s=x, ds/dr=r+1 en el dominio de la EDO.','Integra directamente: s=½r²+r+C. La simetría traslada la parábola verticalmente y cambia C por C+ε.','Vuelve a x=s y y=rs. La fórmula implícita es x=½(y/x)²+y/x+C. En r=−1 hay tangente vertical y x+y=0: corta ahí la solución y(x).']},
 reciprocal:{name:'Recíprocos',eq:'y′ = 2y³(x−y−xy) / [x(x−y)²]',map:'X=x/(1+εx), Y=y/(1+εy)',coords:'r=1/x−1/y, s=1/y',newEq:'ds/dr = −2(r+1)/(r²+2r+2)',integral:'s = −ln(r²+2r+2) + C',back:'1/y = −ln[(1/x−1/y)²+2(1/x−1/y)+2]+C',domain:'Para el cambio: y≠0, s≠0 y r+s≠0. La EDO exige x≠0 y x≠y (r≠0). Añade y=0, solución que el cambio excluye.',steps:['1/X=1/x+ε y 1/Y=1/y+ε. Su diferencia r permanece; s=1/y se traslada.','ds/dx=−y′/y² y dr/dx=−1/x²+y′/y². Divide y simplifica para obtener ds/dr=−2(r+1)/(r²+2r+2).','El numerador es el negativo de la derivada del denominador. Integra: s=−ln[(r+1)²+1]+C. El argumento siempre es positivo.','Usa x=1/(r+s), y=1/s. La simetría cambia C por C+ε. Excluye los polos del mapa y de la EDO. Comprueba por separado y=0.']}
};
function reduction(root){
 root.innerHTML=`<div class="card reduction-picker"><div class="field"><label for="reduction-model">Ecuación que explorar</label><select id="reduction-model"><option value="riccati">1 · Riccati y dilatación</option><option value="ratio">2 · Cociente y traslación</option><option value="reciprocal">3 · Recíprocos y mapa racional</option></select></div><div id="reduction-equation" class="math"></div></div><div class="reduction-controls card"><div id="reduction-constant"></div>${range('reduction-e','Movimiento de la simetría ε',-.6,.6,.02,.2)}</div><div class="two-col reduction-plots"><div class="viz"><div class="viz-header"><span>COORDENADAS ORIGINALES (x,y)</span></div><div id="original-plot"></div>${legend()}</div><div class="viz"><div class="viz-header"><span>COORDENADAS ADAPTADAS (r,s)</span></div><div id="reduced-plot"></div>${legend()}</div></div><div id="reduction-summary" class="card"></div><div class="card derivation"><span class="mini-label">SIGUE EL RAZONAMIENTO</span><div class="derivation-tabs" role="group" aria-label="Pasos de la reducción">${['1. Invariante','2. Cadena','3. Integración','4. Regreso'].map((v,i)=>`<button data-derivation="${i}" class="quiet-button" aria-pressed="${i===0}">${v}</button>`).join('')}</div><div id="derivation-text" aria-live="polite"></div></div><div id="reduction-domain" class="challenge"></div>`;
 let step=0;const setup=()=>{const k=$('#reduction-model').value;$('#reduction-constant').innerHTML=range('reduction-c',k==='riccati'?'Constante C (rama mostrada: C>0)':'Constante de integración C',k==='riccati'?.5:1,k==='riccati'?10:5,.1,k==='riccati'?6:3)+(k==='riccati'?`<div class="field"><label for="riccati-family">Solución</label><select id="riccati-family"><option value="general">Familia y=1/x+2x/(C−x²)</option><option value="plus">Solución r=1: y=1/x</option><option value="minus">Solución r=−1: y=−1/x</option></select></div>`:'');if($('#riccati-family'))$('#riccati-family').onchange=update;bindRanges(['reduction-c'],update);step=0;update();};
 const update=()=>{const k=$('#reduction-model').value,d=reductions[k],C=+$('#reduction-c').value,e=+$('#reduction-e').value,fam=$('#riccati-family')?.value||'general',special=k==='riccati'&&fam!=='general';let original,transformed,rs,rsT,P,PT,R,RT,valid=true;
  if(k==='riccati'){const fn=x=>[x,special?(fam==='plus'?1:-1)/x:riccati(x,C)];original=sampled(fn,.25,4.3);transformed=original.map(p=>transform('odeScale',...p,e));rs=original.map(p=>coordinates(k,...p));rsT=transformed.map(p=>coordinates(k,...p));P=fn(1);PT=transform('odeScale',...P,e);R=coordinates(k,...P);RT=coordinates(k,...PT);}
  else{rs=sampled(r=>[r,reducedSolution(k,r,C)],-3,3);const back=([r,s])=>k==='ratio'?[s,r*s]:[1/(r+s),1/s];const admissible=([r,s])=>k==='ratio'?Math.abs(s)>1e-7&&Math.abs(r+1)>.035:Math.abs(s)>1e-7&&Math.abs(r+s)>1e-7&&Math.abs(r)>.035;
   original=rs.map(p=>admissible(p)?back(p):[NaN,NaN]);const originPoint=back([1,reducedSolution(k,1,C)]);P=originPoint;valid=k==='ratio'?(P[0]+e)*P[0]>0:(1+e*P[0]>0&&1+e*P[1]>0);R=[1,reducedSolution(k,1,C)];
   rsT=rs.map(([r,s])=>[r,s+e]);transformed=rs.map((p,i)=>{if(!admissible(p)||!admissible(rsT[i]))return [NaN,NaN];const [x,y]=back(p);const local=k==='ratio'?(x+e)*x>0:(1+e*x>0&&1+e*y>0);return local?transform(k,x,y,e):[NaN,NaN];});PT=valid?transform(k,...P,e):null;RT=valid?coordinates(k,...PT):null;
  }
  const origBounds=k==='riccati'?[0,4.4,-4.5,4.5]:k==='ratio'?[-.2,8,-8,8]:[-4,4,-4,4];const redBounds=k==='riccati'?[-5,5,-1.7,2.3]:[-3.2,3.2,-3.5,7];const field=special?[]:directionField((r)=>reduced(k,r),redBounds);
  $('#original-plot').innerHTML=plot({title:d.name+': solución original y su imagen bajo la simetría',bounds:origBounds,segments:directionField(odeRhs[k],origBounds),paths:[{data:original},{data:transformed,color:colors.changed,dash:true}],points:[{xy:P,color:colors.original,label:'P'},...(PT?[{xy:PT,label:'Tε(P)'}]:[])]});
  $('#reduced-plot').innerHTML=plot({title:d.name+': invariante r y traslación vertical de s',bounds:redBounds,labels:['r','s'],paths:special?[{data:[[fam==='plus'?1:-1,-2],[fam==='plus'?1:-1,3]]}]:[{data:rs},{data:rsT,color:colors.changed,dash:true}],points:[{xy:R,color:colors.original,label:'(r,s)'},...(RT?[{xy:RT,label:'(r,s+ε)'}]:[])],segments:field});
  $('#reduction-equation').textContent=d.eq;$('#reduction-summary').innerHTML=`<div class="reduction-flow"><div><span class="mini-label">SIMETRÍA</span><p class="math">${d.map}</p></div><div><span class="mini-label">NUEVAS COORDENADAS</span><p class="math">${d.coords}</p></div><div><span class="mini-label">ECUACIÓN REDUCIDA</span><p class="math">${d.newEq}</p></div></div><div class="result-box" aria-live="polite"><p>${special?'r es constante: esta solución aparece como una línea vertical y debe comprobarse en la EDO original.':d.integral}</p><p>${RT?`Punto marcado: r=${fmt(R[0])} → ${fmt(RT[0])}; s=${fmt(R[1])} → ${fmt(RT[1])}. Solo s cambia, en ${fmt(e)}.`:'El punto marcado no puede seguir este flujo sin cruzar un polo. Ajusta ε.'}</p><p class="helper">${k==='riccati'&&!special?'La imagen tiene C̄=e^(2ε)C='+fmt(Math.exp(2*e)*C)+'.':k!=='riccati'?'La imagen tiene C̄=C+ε='+fmt(C+e)+'.':''} Las líneas se interrumpen en los polos y los puntos excluidos; el campo reducido muestra ds/dr.</p></div>`;
  $('#derivation-text').innerHTML=`<h3>${['Elige la etiqueta constante','Transforma las derivadas','Integra la ecuación separable','Recupera la solución original'][step]}</h3><p>${d.steps[step]}</p>`;document.querySelectorAll('[data-derivation]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.derivation)===step));$('#reduction-domain').innerHTML=`<strong>Dominios y soluciones que debes recuperar</strong>${d.domain}`;
 };document.querySelectorAll('[data-derivation]').forEach(b=>b.onclick=()=>{step=+b.dataset.derivation;update();});$('#reduction-model').onchange=setup;bindRanges(['reduction-e'],update);setup();
}
export function renderArrigo(section,root){[geometry,group,invariance,reduction][section-1](root);}
